$('#zoomIn').onclick=()=>zoom(.8);$('#zoomOut').onclick=()=>zoom(1.25);$('#resetMap').onclick=()=>{stopMapTween(svg);box=[786,47,946,1037];setBox();};svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:.89);},{passive:false});svg.onpointerdown=e=>{if(e.button!==0)return;stopMapTween(svg);svg.dataset.pressedBuilding=e.target.closest?.('[data-building]')?.dataset.building||'';pointers.set(e.pointerId,[e.clientX,e.clientY]);svg.setPointerCapture(e.pointerId);drag=[e.clientX,e.clientY];moved=false;};svg.onpointermove=e=>{if(!pointers.has(e.pointerId))return;const old=pointers.get(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);if(Math.hypot(e.clientX-old[0],e.clientY-old[1])>2)moved=true;if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);if(pinch)zoom(pinch/d);pinch=d;drag=null;}else if(drag){const r=svg.getBoundingClientRect(),scale=Math.max(box[2]/r.width,box[3]/r.height);box[0]-=(e.clientX-drag[0])*scale;box[1]-=(e.clientY-drag[1])*scale;drag=[e.clientX,e.clientY];setBox();}};svg.onpointerup=e=>{pointers.delete(e.pointerId);drag=null;pinch=null;if(moved)return;const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform(svg.getScreenCTM().inverse());const pin=svg.dataset.pressedBuilding;svg.dataset.pressedBuilding='';if(pin){showBuilding(pin);return;}if(state.pick){const geo=mapToGeo(p);if(!inCampus(geo)){toast(t('请在主校园区域内选择参考点。','Choose a point within the main campus.'));return;}if(state.stepFree){toast(t('无台阶演示需要使用已收录的起点。','Choose a named starting point for the step-free demo.'));return;}chooseOrigin({id:'map-reference',...geo,x:p.x,y:p.y,name:'Map reference',zh:'地图参考点'});return;}};svg.onpointercancel=e=>{pointers.delete(e.pointerId);drag=null;pinch=null;};
